contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log1) public {
        bool setReverted;
        c.SetLogFile(log1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setReverted = true; } else { setReverted = false; }

        assert(setReverted == false);
    }

    receive() external payable {}
}

