pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address log1) internal {
        bool setReverted;
        try c.SetLogFile(log1) { setReverted = false; } catch { setReverted = true; }
        assertTrue(setReverted == false);
    }

    function testFuzz_run(address log1) public {
        vm.assume(log1.code.length == 0 && uint160(log1) > 0xffff && log1 != address(this) && log1 != address(c) && log1 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && log1 != 0x000000000000000000636F6e736F6c652e6c6f67 && log1 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && log1 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(log1);
    }

    receive() external payable {}
}
